// Command generate-device-issues publishes the device-issue vocabulary from the
// descriptor table in internal/kernel/deviceissue, and gates it.
//
// It writes two artefacts. Do not edit them by hand:
//
//	docs/vocabularies/device-issues.json      the machine-readable set
//	docs/src/content/docs/device-issues.md    the reference a client reads
//
// A committed reason the code does not declare fails the run unless
// -allow-removals is set, because a client may still use it. With -check it
// writes nothing and fails when a committed artefact differs from the
// generated one.
//
// Run via: make generate-device-issues, gated by make device-issues-check.
package main

import (
	"errors"
	"flag"
	"fmt"
	"os"

	"github.com/prusa3d/prusa-connect/internal/codegen"
	"github.com/prusa3d/prusa-connect/internal/kernel/deviceissue"
)

const (
	defaultCataloguePath = "docs/vocabularies/device-issues.json"
	defaultReferencePath = "docs/src/content/docs/device-issues.md"

	// generatedNotice is the first thing in both artefacts.
	generatedNotice = "Generated by 'make generate-device-issues' from the descriptor table this " +
		"build links. Do not edit: change the table in Go and regenerate."
)

type options struct {
	cataloguePath string
	referencePath string
	check         bool
	allowRemovals bool
}

func main() {
	opts := options{}

	flag.StringVar(&opts.cataloguePath, "catalogue", defaultCataloguePath,
		"path of the machine-readable device-issue set")
	flag.StringVar(&opts.referencePath, "reference", defaultReferencePath,
		"path of the published device-issue reference")
	flag.BoolVar(&opts.check, "check", false,
		"compare the committed artefacts against the generated ones and write nothing")
	flag.BoolVar(&opts.allowRemovals, "allow-removals", false,
		"let a reason disappear. A client is still branching on it: for a deliberate retirement in a "+
			"breaking release only")
	flag.Parse()

	if err := run(deviceissue.Docs(), opts); err != nil {
		fmt.Fprintf(os.Stderr, "generate-device-issues: %v\n", err)
		os.Exit(1)
	}
}

func run(entries []deviceissue.Doc, opts options) error {
	committed, err := codegen.ReadCatalogue[catalogueFile](opts.cataloguePath)
	if err != nil {
		return err
	}

	if err = errors.Join(
		checkDescribed(entries),
		checkDrift(committed, entries, opts.allowRemovals, !opts.check),
	); err != nil {
		return err
	}

	machine, err := renderCatalogue(entries)
	if err != nil {
		return err
	}

	human := renderReference(entries)

	if opts.check {
		return errors.Join(
			compareFile(opts.cataloguePath, machine),
			compareFile(opts.referencePath, human),
		)
	}

	if err = codegen.WriteFile(opts.cataloguePath, machine); err != nil {
		return err
	}

	if err = codegen.WriteFile(opts.referencePath, human); err != nil {
		return err
	}

	fmt.Fprintf(os.Stderr, "OK device-issue set: %s (%d reasons)\n", opts.cataloguePath, len(entries))
	fmt.Fprintf(os.Stderr, "OK device-issue reference: %s\n", opts.referencePath)

	return nil
}
